tool_input.command:
mkdir -p work && cat > work/cams.mjs <<'EOF'
import fs from 'fs';
const cams = JSON.parse(fs.readFileSync('inputs/cameras.json','utf8')).views;
// quaternion rotate vector
function rot(q, v){
  const [x,y,z,w]=q;
  // q * v * q^-1
  const ux=x,uy=y,uz=z;
  const dot=ux*v[0]+uy*v[1]+uz*v[2];
  const cx=uy*v[2]-uz*v[1], cy=uz*v[0]-ux*v[2], cz=ux*v[1]-uy*v[0];
  return [
    2*dot*ux + (w*w-(ux*ux+uy*uy+uz*uz))*v[0] + 2*w*cx,
    2*dot*uy + (w*w-(ux*ux+uy*uy+uz*uz))*v[1] + 2*w*cy,
    2*dot*uz + (w*w-(ux*ux+uy*uy+uz*uz))*v[2] + 2*w*cz,
  ];
}
for(const c of cams){
  const f = rot(c.quat, [0,0,-1]); // forward
  const yaw = Math.atan2(f[0], -f[2])*180/Math.PI; // 0 = -z, 90 = +x
  const pitch = Math.asin(f[1])*180/Math.PI;
  console.log(c.name.replace('.JPG',''), 'pos', c.pos.map(v=>v.toFixed(2)).join(','), 'fwd', f.map(v=>v.toFixed(2)).join(','), 'yaw', yaw.toFixed(0), 'pitch', pitch.toFixed(0));
}
EOF
node work/cams.mjs
